/bin/zsh -lc "python3 -c 'import json; terms={\"완료\",\"배포\",\"검토\",\"판정\",\"집계\",\"로그\",\"대시보드\",\"내보내기\",\"필터\",\"삭제\",\"보관\",\"확인\"};
def walk(x):
 if isinstance(x,dict):
  if x.get(\"lemma\") in terms: print(json.dumps(x,ensure_ascii=False))
  else:
   for v in x.values(): walk(v)
 elif isinstance(x,list):
  for v in x: walk(v)
for path in [\"lexicon/core.json\",\"lexicon/domains/software.json\"]:
 with open(path) as f: walk(json.load(f))'"

